#[test]
fn euclidean_layout_matches_python_serial() {
    let mut rng_state = RNG_STATE;
    let mut embedding =
        ndarray::Array2::from_shape_fn((N_VERTICES, 2), |(i, d)| INIT_EMBEDDING[i][d] as f32);
    let _ = optimize_layout_euclidean(
        &mut embedding,
        TailEmbedding::Same,
        HEAD,
        TAIL,
        N_EPOCHS,
        N_VERTICES,
        EPOCHS_PER_SAMPLE,
        A,
        B,
        &mut rng_state,
        1.0,
        1.0,
        5.0,
        false,
        false,
        false,
        None,
        None,
        false,
    );
    // Statistical parity: serial kernels track the numba serial kernel;
    // fastmath reassociation in rdist accumulates drift over epochs.
    let mut max_err = 0.0f64;
    for i in 0..N_VERTICES {
        for d in 0..2 {
            let got = f64::from(embedding[[i, d]]);
            let want = RESULT[i][d];
            max_err = max_err.max((got - want).abs());
        }
    }
    assert!(max_err < 0.01, "max abs error {max_err}");
}
